   104→        return stats;
   105→    }
   106→
   107→    // === 계획 생성 (핵심 로직) ===
   108→
   109→    // WHERE 조건 기반 실행 계획 선택
   110→    func plan_query(q: query.Query, stats: TableStats, has_int_idx: bool, has_str_idx: bool) -> ExecPlan {
   111→        // 기본 계획: 풀스캔
   112→        let plan = ExecPlan{
   113→            plan_type:  PLAN_FULL_SCAN,
   114→            index_col:  -1,
   115→            est_rows:   stats.row_count,
   116→            cost:       stats.row_count,  // 비용 = 행 수
   117→            error_code: PLAN_OK,
   118→        };
   119→
   120→        // WHERE 절이 없으면 풀스캔
   121→        if q.where_count == 0 {
   122→            return plan;
   123→        }
   124→
   125→        // 복합 WHERE 절 (AND)은 풀스캔 (간단화)
   126→        if q.where_count > 1 {
   127→            return plan;
   128→        }
   129→
   130→        let where_clause = q.wheres[0];
   131→        let col_idx = where_clause.col_idx;
   132→
   133→        // 컬럼 범위 검증
   134→        if col_idx < 0 || col_idx >= stats.col_count {
   135→            plan.error_code = PLAN_ERR_NO_STATS;
   136→            return plan;
   137→        }
   138→
   139→        // ===== INT 인덱스 고려 =====
   140→        if has_int_idx && !where_clause.is_str {
   141→            // EQUALITY 비교 (==)
   142→            if where_clause.op == query.OP_EQ {
   143→                plan.plan_type = PLAN_INDEX_EQ;
   144→                plan.index_col = col_idx;
   145→                plan.est_rows = 1;
   146→                plan.cost = log_cost(stats.row_count) + 1;
   147→                return plan;
   148→            }
   149→
   150→            // RANGE 비교 (>, <, >=, <=)
   151→            if where_clause.op == query.OP_GT || where_clause.op == query.OP_LT ||
   152→               where_clause.op == query.OP_GE || where_clause.op == query.OP_LE {
   153→                let range_est = range_estimate(stats, col_idx, where_clause.op, where_clause.int_val);
   154→                plan.plan_type = PLAN_INDEX_RANGE;
   155→                plan.index_col = col_idx;
   156→                plan.est_rows = range_est;
   157→                plan.cost = log_cost(stats.row_count) + range_est;
   158→
   159→                // 범위가 작으면 인덱스 사용, 크면 풀스캔 (휴리스틱)
   160→                if plan.cost >= stats.row_count {
   161→                    plan.plan_type = PLAN_FULL_SCAN;
   162→                    plan.cost = stats.row_count;
   163→                }
   164→                return plan;
   165→            }
   166→        }
   167→
   168→        // ===== STR 인덱스 고려 =====
   169→        if has_str_idx && where_clause.is_str {
   170→            if where_clause.op == query.OP_LIKE {
   171→                // LIKE: 접두어 매칭 (B+Tree 범위 스캔)
   172→                let like_est = stats.row_count / 10;  // 휴리스틱: 전체의 1/10
   173→                plan.plan_type = PLAN_INDEX_LIKE;
   174→                plan.index_col = col_idx;
   175→                plan.est_rows = like_est;
   176→                plan.cost = log_cost(stats.row_count) + like_est;
   177→                return plan;
   178→            }
   179→        }
   180→
   181→        // 기본: 풀스캔
   182→        return plan;
   183→    }
   184→
   185→    // === 비용 추정 헬퍼 함수 ===
   186→
   187→    // log2(n) 근사 (비트 길이 이용)
   188→    @inline
   189→    func log_cost(n: i32) -> i32 {
   190→        if n <= 1 { return 0; }
   191→        if n <= 2 { return 1; }
   192→        if n <= 4 { return 2; }
   193→        if n <= 8 { return 3; }
   194→        if n <= 16 { return 4; }
   195→        if n <= 32 { return 5; }
   196→        if n <= 64 { return 6; }
   197→        if n <= 128 { return 7; }
   198→        if n <= 256 { return 8; }
   199→        if n <= 512 { return 9; }
   200→        if n <= 1024 { return 10; }
   201→        return 11;
   202→    }
   203→
   204→    // 범위 조건의 결과 행 수 추정
   205→    func range_estimate(stats: TableStats, col_idx: i32, op: i32, value: i64) -> i32 {
   206→        let col_min = stats.col_min[col_idx];
   207→        let col_max = stats.col_max[col_idx];
   208→        let col_range = col_max - col_min;
   209→
   210→        // 범위가 0이면 전체 반환
   211→        if col_range == 0 {
   212→            return stats.row_count;
   213→        }
   214→
   215→        // 조건별 추정 (균등 분포 가정)
   216→        if op == query.OP_GT {
   217→            // value < col <= col_max
   218→            if value >= col_max {
   219→                return 0;
   220→            }
   221→            let dist = (col_max - value) * 100 / col_range;
   222→            let est = (stats.row_count * dist) / 100;
   223→            if est < 1 { est = 1; }
   224→            return est;
   225→        }
   226→
   227→        if op == query.OP_LT {
   228→            // col_min <= col < value
   229→            if value <= col_min {
   230→                return 0;
   231→            }
   232→            let dist = (value - col_min) * 100 / col_range;
   233→            let est = (stats.row_count * dist) / 100;
   234→            if est < 1 { est = 1; }
   235→            return est;
   236→        }
   237→
   238→        if op == query.OP_GE {
   239→            // value <= col <= col_max
   240→            if value > col_max {
   241→                return 0;
   242→            }
   243→            let dist = (col_max - value) * 100 / col_range;
   244→            let est = (stats.row_count * dist) / 100 + 1;
   245→            if est < 1 { est = 1; }
   246→            return est;
   247→        }
