     1→// ============================================================================
     2→// FreeLang Index 모듈 - B+Tree 인덱스 (배열 기반)
     3→// ============================================================================
     4→// 목표: schema.fl + query.fl의 풀 스캔 병목 해결 (O(n) → O(log n))
     5→// 원리:
     6→//   1. 노드 풀: 배열 기반 노드 저장 (포인터 대신 인덱스)
     7→//   2. 트리 탐색: while 루프로 루트부터 리프까지 (재귀 없음)
     8→//   3. 범위 스캔: 리프 노드 연결 리스트 순회
     9→//   4. 삽입/삭제: 노드 분할/합병으로 균형 유지
    10→// 구조:
    11→//   - 상수 정의 (차수, 제한값)
    12→//   - BTreeNode, BTreeIndex 구조체
    13→//   - 탐색 함수 (find_leaf, binary_search)
    14→//   - 삽입/삭제 함수
    15→//   - 범위 스캔 함수
    16→// ============================================================================
    17→
    18→module index {
    19→    // === 상수: B+Tree 설정 ===
    20→    const ORDER:       i32 = 4;    // 차수 (최대 2*ORDER 키)
    21→    const MAX_KEYS:    i32 = 8;    // 노드당 최대 키
    22→    const MAX_PTRS:    i32 = 9;    // 노드당 최대 포인터 (자식)
    23→    const MAX_NODES:   i32 = 512;  // 전체 노드 풀 크기
    24→
    25→    // === 상수: 에러 코드 ===
    26→    const IDX_OK:         i32 = 0;
    27→    const IDX_ERR_FULL:   i32 = 50;
    28→    const IDX_ERR_DUP:    i32 = 51;
    29→    const IDX_ERR_NOTFOUND: i32 = 52;
    30→
    31→    // === 데이터 구조체 ===
    32→
    33→    struct BTreeNode {
    34→        is_leaf:    bool;
    35→        key_count:  i32;
    36→        keys:       [i64];      // 정렬된 키 배열
    37→        row_ids:    [i64];      // 리프 노드: 각 키의 row_id
    38→        children:   [i32];      // 내부 노드: 자식 인덱스
    39→        parent:     i32;        // 부모 인덱스 (-1 = 루트)
    40→        next_leaf:  i32;        // 다음 리프 노드 (-1 = 마지막)
    41→        prev_leaf:  i32;        // 이전 리프 노드 (-1 = 처음)
    42→    }
    43→
    44→    struct BTreeIndex {
    45→        col_idx:    i32;
    46→        root:       i32;        // 루트 노드 인덱스
    47→        nodes:      [BTreeNode];
    48→        node_count: i32;
    49→        height:     i32;
    50→        key_count:  i64;
    51→    }
    52→
    53→    // === 팩토리 함수 ===
    54→
    55→    func index_new(col_idx: i32) -> BTreeIndex {
    56→        let root_node = BTreeNode{
    57→            is_leaf:    true,
    58→            key_count:  0,
    59→            keys:       make([i64], MAX_KEYS),
    60→            row_ids:    make([i64], MAX_KEYS),
    61→            children:   make([i32], MAX_PTRS),
    62→            parent:     -1,
    63→            next_leaf:  -1,
    64→            prev_leaf:  -1,
    65→        };
    66→        let nodes = make([BTreeNode], MAX_NODES);
    67→        nodes[0] = root_node;
    68→        return BTreeIndex{
    69→            col_idx:    col_idx,
    70→            root:       0,
    71→            nodes:      nodes,
    72→            node_count: 1,
    73→            height:     1,
    74→            key_count:  0,
    75→        };
    76→    }
    77→
    78→    // === 핵심 탐색 함수 ===
    79→
    80→    // 키가 속할 리프 노드 찾기
    81→    func (idx: *BTreeIndex) find_leaf(key: i64) -> i32 {
    82→        let current = idx.root;
    83→        let i = 0;
    84→        for i = 0; i < 100; i = i + 1 {  // 최대 높이 100 제한
    85→            let node = idx.nodes[current];
    86→            if node.is_leaf {
    87→                return current;
    88→            }
    89→            // 자식 노드 선택: key < keys[0] → children[0], 그 외 이진탐색
    90→            let child_idx = 0;
    91→            let j = 0;
    92→            for j = 0; j < node.key_count; j = j + 1 {
    93→                if key < node.keys[j] {
    94→                    break;
    95→                }
    96→                child_idx = j + 1;
    97→            }
    98→            if child_idx >= MAX_PTRS {
    99→                child_idx = node.key_count;
   100→            }
   101→            current = node.children[child_idx];
   102→        }
   103→        return current;
   104→    }
   105→
   106→    // 리프 노드에서 키의 위치 찾기 (이진 탐색)
   107→    func binary_search_leaf(node: BTreeNode, key: i64) -> (i32, bool) {
