// ============================================================================
// FreeLang IR Builder 모듈 - 물리 계획을 3-Address Code (IR)로 변환
// ============================================================================
// 목표: PhysicalPlan (planner.fl) → IR Instructions (21 opcodes) 변환
// 원리:
//   1. 21개 IR Opcodes: LOAD_INT, LOAD_COL, CMP, JZ, JMP, CALL, NEXT_ROW, AGG 등
//   2. 온도 레지스터 할당: %r0, %r1, ... %r31 (최대 64개)
//   3. 레이블 생성 및 관리: label_loop_start, label_skip_filter 등
//   4. 물리 계획의 각 연산을 IR 명령어로 변환
// 구조:
//   - IRInstruction 구조체 (opcode + 연산 정보)
//   - IRBuilder 구조체 (명령어 배열 + 레지스터/레이블 할당)
//   - IR 생성 함수 (ir_emit_*)
//   - 물리 계획 변환 (ir_build_from_physical)
// ============================================================================

module ir_builder {
    // === 21개 IR Opcodes ===
    // 정수 연산
    const IR_LOAD_INT:  i32 = 1;    // %dst = immediate_int_value
    const IR_LOAD_STR:  i32 = 2;    // %dst = "string_value"
    const IR_LOAD_COL:  i32 = 3;    // %dst = current_row[col_idx]
    const IR_STORE_COL: i32 = 4;    // current_row[col_idx] = %src

    // 산술 연산
    const IR_ADD:       i32 = 5;    // %dst = %src1 + %src2
    const IR_SUB:       i32 = 6;    // %dst = %src1 - %src2
    const IR_MUL:       i32 = 7;    // %dst = %src1 * %src2
    const IR_DIV:       i32 = 8;    // %dst = %src1 / %src2

    // 비교 및 분기
    const IR_CMP:       i32 = 9;    // flags = cmp(%src1, %src2)
    const IR_JMP:       i32 = 10;   // goto label_id
    const IR_JZ:        i32 = 11;   // if zero goto label_id
    const IR_JNZ:       i32 = 12;   // if not zero goto label_id

    // 함수 호출
    const IR_CALL:      i32 = 13;   // %dst = call func_name(args)
    const IR_RET:       i32 = 14;   // return %src

    // 레이블 및 이동
    const IR_LABEL:     i32 = 15;   // label: (no operation)
    const IR_MOV:       i32 = 16;   // %dst = %src

    // 스택 연산
    const IR_PUSH:      i32 = 17;   // push %src
    const IR_POP:       i32 = 18;   // pop %dst

    // NOP
    const IR_NOP:       i32 = 19;   // no operation

    // 테이블 스캔
    const IR_NEXT_ROW:  i32 = 20;   // 다음 행으로 이동 (table_idx)

    // 집계
    const IR_AGGREGATE: i32 = 21;   // aggregate(agg_type, dst_reg, src_reg)

    // === 에러 코드 ===
    const IR_OK:             i32 = 0;
    const IR_ERR_FULL:       i32 = 100;  // 명령어 배열 가득 참
    const IR_ERR_INVALID_OP: i32 = 101;  // 유효하지 않은 opcode
    const IR_ERR_NO_REG:     i32 = 102;  // 온도 레지스터 부족

    // === 제한값 ===
    const MAX_IR_OPS:    i32 = 256;
    const MAX_TEMP_REGS: i32 = 64;
    const MAX_LABELS:    i32 = 128;

    // === 데이터 구조체 ===

    // 단일 IR 명령어
    struct IRInstruction {
        opcode:    i32;       // IR_LOAD_INT, IR_ADD 등
        dst_reg:   i32;       // 목적 레지스터 (%r0, %r1, ... as 0, 1, ...)
        src1_reg:  i32;       // 첫 번째 원본 레지스터
        src2_reg:  i32;       // 두 번째 원본 레지스터
        imm_int:   i64;       // 즉시값 (정수)
        imm_str:   string;    // 즉시값 (문자열)
        label_id:  i32;       // 레이블 ID (분기 시)
        func_name: string;    // 함수명 (CALL 시)
        col_idx:   i32;       // 컬럼 인덱스 (LOAD_COL, STORE_COL 시)
        table_idx: i32;       // 테이블 인덱스 (NEXT_ROW 시)
        agg_type:  i32;       // 집계 타입 (AGGREGATE 시)
    }

    // IR 빌더 (상태 관리)
    struct IRBuilder {
        instructions:  [IRInstruction];   // 명령어 배열 (MAX_IR_OPS)
        instr_count:   i32;               // 현재 명령어 개수
        next_temp_reg: i32;               // 다음 온도 레지스터 번호
        next_label_id: i32;               // 다음 레이블 ID
        error_code:    i32;               // 마지막 에러 코드
    }

    // === 팩토리 함수 ===

    func ir_builder_new() -> IRBuilder {
        let instructions = make([IRInstruction], MAX_IR_OPS);
        return IRBuilder{
            instructions:  instructions,
            instr_count:   0,
            next_temp_reg: 0,
            next_label_id: 0,
            error_code:    IR_OK,
        };
    }

    // === 공개 API: 레지스터 & 레이블 할당 ===

    // 새로운 온도 레지스터 할당
    func (ib: *IRBuilder) ir_new_temp_reg() -> i32 {
        if ib.next_temp_reg >= MAX_TEMP_REGS {
            ib.error_code = IR_ERR_NO_REG;
            return -1;
        }
        let reg = ib.next_temp_reg;
        ib.next_temp_reg = ib.next_temp_reg + 1;
        return reg;
    }

    // 새로운 레이블 생성
    func (ib: *IRBuilder) ir_new_label() -> i32 {
        if ib.next_label_id >= MAX_LABELS {
            ib.error_code = IR_ERR_FULL;
            return -1;
        }
        let label_id = ib.next_label_id;
        ib.next_label_id = ib.next_label_id + 1;
        return label_id;
    }

    // === 공개 API: IR 명령어 생성 ===

    // LOAD_INT: 정수 상수 로드
    func (ib: *IRBuilder) ir_emit_load_int(dst_reg: i32, val: i64) -> i32 {
        if ib.instr_count >= MAX_IR_OPS {
            ib.error_code = IR_ERR_FULL;
            return IR_ERR_FULL;
        }

        let instr = IRInstruction{
            opcode:    IR_LOAD_INT,
            dst_reg:   dst_reg,
            src1_reg:  -1,
            src2_reg:  -1,
            imm_int:   val,
            imm_str:   "",
            label_id:  -1,
            func_name: "",
            col_idx:   -1,
            table_idx: -1,
            agg_type:  -1,
        };

        ib.instructions[ib.instr_count] = instr;
        ib.instr_count = ib.instr_count + 1;
        return IR_OK;
    }

    // LOAD_STR: 문자열 상수 로드
    func (ib: *IRBuilder) ir_emit_load_str(dst_reg: i32, str_val: string) -> i32 {
        if ib.instr_count >= MAX_IR_OPS {
            ib.error_code = IR_ERR_FULL;
            return IR_ERR_FULL;
        }

        let instr = IRInstruction{
            opcode:    IR_LOAD_STR,
            dst_reg:   dst_reg,
            src1_reg:  -1,
            src2_reg:  -1,
            imm_int:   0,
            imm_str:   str_val,
            label_id:  -1,
            func_name: "",
            col_idx:   -1,
            table_idx: -1,
            agg_type:  -1,
        };

        ib.instructions[ib.instr_count] = instr;
        ib.instr_count = ib.instr_count + 1;
        return IR_OK;
    }

    // LOAD_COL: 현재 행의 컬럼 값 로드
    func (ib: *IRBuilder) ir_emit_load_col(dst_reg: i32, col_idx: i32) -> i32 {
        if ib.instr_count >= MAX_IR_OPS {
            ib.error_code = IR_ERR_FULL;
            return IR_ERR_FULL;
        }

        let instr = IRInstruction{
            opcode:    IR_LOAD_COL,
            dst_reg:   dst_reg,
            src1_reg:  -1,
            src2_reg:  -1,
            imm_int:   0,
            imm_str:   "",
            label_id:  -1,
            func_name: "",
            col_idx:   col_idx,
            table_idx: -1,
            agg_type:  -1,
        };

        ib.instructions[ib.instr_count] = instr;
        ib.instr_count = ib.instr_count + 1;
        return IR_OK;
    }

    // STORE_COL: 현재 행의 컬럼에 값 저장
    func (ib: *IRBuilder) ir_emit_store_col(col_idx: i32, src_reg: i32) -> i32 {
        if ib.instr_count >= MAX_IR_OPS {
            ib.error_code = IR_ERR_FULL;
            return IR_ERR_FULL;
        }

        let instr = IRInstruction{
            opcode:    IR_STORE_COL,
            dst_reg:   -1,
            src1_reg:  src_reg,
            src2_reg:  -1,
            imm_int:   0,
            imm_str:   "",
            label_id:  -1,
            func_name: "",
            col_idx:   col_idx,
            table_idx: -1,
            agg_type:  -1,
        };

        ib.instructions[ib.instr_count] = instr;
        ib.instr_count = ib.instr_count + 1;
        return IR_OK;
    }

    // ADD: 두 레지스터 덧셈
    func (ib: *IRBuilder) ir_emit_add(dst_reg: i32, src1_reg: i32, src2_reg: i32) -> i32 {
        if ib.instr_count >= MAX_IR_OPS {
            ib.error_code = IR_ERR_FULL;
            return IR_ERR_FULL;
        }

        let instr = IRInstruction{
            opcode:    IR_ADD,
            dst_reg:   dst_reg,
            src1_reg:  src1_reg,
            src2_reg:  src2_reg,
            imm_int:   0,
            imm_str:   "",
            label_id:  -1,
            func_name: "",
            col_idx:   -1,
            table_idx: -1,
            agg_type:  -1,
        };

        ib.instructions[ib.instr_count] = instr;
        ib.instr_count = ib.instr_count + 1;
        return IR_OK;
    }

    // SUB: 두 레지스터 뺄셈
    func (ib: *IRBuilder) ir_emit_sub(dst_reg: i32, src1_reg: i32, src2_reg: i32) -> i32 {
        if ib.instr_count >= MAX_IR_OPS {
            ib.error_code = IR_ERR_FULL;
            return IR_ERR_FULL;
        }

        let instr = IRInstruction{
            opcode:    IR_SUB,
            dst_reg:   dst_reg,
            src1_reg:  src1_reg,
            src2_reg:  src2_reg,
            imm_int:   0,
            imm_str:   "",
            label_id:  -1,
            func_name: "",
            col_idx:   -1,
            table_idx: -1,
            agg_type:  -1,
        };

        ib.instructions[ib.instr_count] = instr;
        ib.instr_count = ib.instr_count + 1;
        return IR_OK;
    }

    // MUL: 두 레지스터 곱셈
    func (ib: *IRBuilder) ir_emit_mul(dst_reg: i32, src1_reg: i32, src2_reg: i32) -> i32 {
        if ib.instr_count >= MAX_IR_OPS {
            ib.error_code = IR_ERR_FULL;
            return IR_ERR_FULL;
        }

        let instr = IRInstruction{
            opcode:    IR_MUL,
            dst_reg:   dst_reg,
            src1_reg:  src1_reg,
            src2_reg:  src2_reg,
            imm_int:   0,
            imm_str:   "",
            label_id:  -1,
            func_name: "",
            col_idx:   -1,
            table_idx: -1,
            agg_type:  -1,
        };

        ib.instructions[ib.instr_count] = instr;
        ib.instr_count = ib.instr_count + 1;
        return IR_OK;
    }

    // DIV: 두 레지스터 나눗셈
    func (ib: *IRBuilder) ir_emit_div(dst_reg: i32, src1_reg: i32, src2_reg: i32) -> i32 {
        if ib.instr_count >= MAX_IR_OPS {
            ib.error_code = IR_ERR_FULL;
            return IR_ERR_FULL;
        }

        let instr = IRInstruction{
            opcode:    IR_DIV,
            dst_reg:   dst_reg,
            src1_reg:  src1_reg,
            src2_reg:  src2_reg,
            imm_int:   0,
            imm_str:   "",
            label_id:  -1,
            func_name: "",
            col_idx:   -1,
            table_idx: -1,
            agg_type:  -1,
        };

        ib.instructions[ib.instr_count] = instr;
        ib.instr_count = ib.instr_count + 1;
        return IR_OK;
    }

    // CMP: 두 레지스터 비교 (flags 설정)
    func (ib: *IRBuilder) ir_emit_cmp(src1_reg: i32, src2_reg: i32) -> i32 {
        if ib.instr_count >= MAX_IR_OPS {
            ib.error_code = IR_ERR_FULL;
            return IR_ERR_FULL;
        }

        let instr = IRInstruction{
            opcode:    IR_CMP,
            dst_reg:   -1,
            src1_reg:  src1_reg,
            src2_reg:  src2_reg,
            imm_int:   0,
            imm_str:   "",
            label_id:  -1,
            func_name: "",
            col_idx:   -1,
            table_idx: -1,
            agg_type:  -1,
        };

        ib.instructions[ib.instr_count] = instr;
        ib.instr_count = ib.instr_count + 1;
        return IR_OK;
    }

    // JMP: 무조건 점프
    func (ib: *IRBuilder) ir_emit_jmp(label_id: i32) -> i32 {
        if ib.instr_count >= MAX_IR_OPS {
            ib.error_code = IR_ERR_FULL;
            return IR_ERR_FULL;
        }

        let instr = IRInstruction{
            opcode:    IR_JMP,
            dst_reg:   -1,
            src1_reg:  -1,
            src2_reg:  -1,
            imm_int:   0,
            imm_str:   "",
            label_id:  label_id,
            func_name: "",
            col_idx:   -1,
            table_idx: -1,
            agg_type:  -1,
        };

        ib.instructions[ib.instr_count] = instr;
        ib.instr_count = ib.instr_count + 1;
        return IR_OK;
    }

    // JZ: Zero flag가 설정되면 점프
    func (ib: *IRBuilder) ir_emit_jz(label_id: i32) -> i32 {
        if ib.instr_count >= MAX_IR_OPS {
            ib.error_code = IR_ERR_FULL;
            return IR_ERR_FULL;
        }

        let instr = IRInstruction{
            opcode:    IR_JZ,
            dst_reg:   -1,
            src1_reg:  -1,
            src2_reg:  -1,
            imm_int:   0,
            imm_str:   "",
            label_id:  label_id,
            func_name: "",
            col_idx:   -1,
            table_idx: -1,
            agg_type:  -1,
        };

        ib.instructions[ib.instr_count] = instr;
        ib.instr_count = ib.instr_count + 1;
        return IR_OK;
    }

    // JNZ: Zero flag가 설정되지 않으면 점프
    func (ib: *IRBuilder) ir_emit_jnz(label_id: i32) -> i32 {
        if ib.instr_count >= MAX_IR_OPS {
            ib.error_code = IR_ERR_FULL;
            return IR_ERR_FULL;
        }

        let instr = IRInstruction{
            opcode:    IR_JNZ,
            dst_reg:   -1,
            src1_reg:  -1,
            src2_reg:  -1,
            imm_int:   0,
            imm_str:   "",
            label_id:  label_id,
            func_name: "",
            col_idx:   -1,
            table_idx: -1,
            agg_type:  -1,
        };

        ib.instructions[ib.instr_count] = instr;
        ib.instr_count = ib.instr_count + 1;
        return IR_OK;
    }

    // CALL: 함수 호출
    func (ib: *IRBuilder) ir_emit_call(dst_reg: i32, func_name: string, arg_count: i32) -> i32 {
        if ib.instr_count >= MAX_IR_OPS {
            ib.error_code = IR_ERR_FULL;
            return IR_ERR_FULL;
        }

        let instr = IRInstruction{
            opcode:    IR_CALL,
            dst_reg:   dst_reg,
            src1_reg:  -1,
            src2_reg:  arg_count,  // arg_count를 src2_reg에 저장
            imm_int:   0,
            imm_str:   "",
            label_id:  -1,
            func_name: func_name,
            col_idx:   -1,
            table_idx: -1,
            agg_type:  -1,
        };

        ib.instructions[ib.instr_count] = instr;
        ib.instr_count = ib.instr_count + 1;
        return IR_OK;
