        if instr.opcode == IR_LOAD_INT {
            opcode_str = "LOAD_INT";
            result = opcode_str + " " + reg_name(instr.dst_reg) + ", " + str_from_i32(instr.imm_int as i32);
        } else if instr.opcode == IR_LOAD_STR {
            opcode_str = "LOAD_STR";
