        } else if instr.opcode == IR_LOAD_COL {
            opcode_str = "LOAD_COL";
            result = opcode_str + " " + reg_name(instr.dst_reg) + ", col" + str_from_i32(instr.col_idx);
        } else if instr.opcode == IR_ADD {
            opcode_str = "ADD";
            result = opcode_str + " " + reg_name(instr.dst_reg) + ", " + reg_name(instr.src1_reg) + ", " + reg_name(instr.src2_reg);
        } else if instr.opcode == IR_CMP {
            opcode_str = "CMP";
            result = opcode_str + " " + reg_name(instr.src1_reg) + ", " + reg_name(instr.src2_reg);
        } else if instr.opcode == IR_JZ {
            opcode_str = "JZ";
            result = opcode_str + " " + label_name(instr.label_id);
        } else if instr.opcode == IR_JMP {
            opcode_str = "JMP";
            result = opcode_str + " " + label_name(instr.label_id);
        } else if instr.opcode == IR_LABEL {
