            result = label_name(instr.label_id) + ":";
        } else if instr.opcode == IR_NEXT_ROW {
            opcode_str = "NEXT_ROW";
            result = opcode_str + " table" + str_from_i32(instr.table_idx);
        } else if instr.opcode == IR_NOP {
