// ============================================================================
// FreeLang IR Builder 모듈 - 물리 계획을 3-Address Code (IR)로 변환
// ============================================================================
// 목표: PhysicalPlan (planner.fl) → IR Instructions (21 opcodes) 변환
// 원리:
//   1. 21개 IR Opcodes: LOAD_INT, LOAD_COL, CMP, JZ, JMP, CALL, NEXT_ROW, AGG 등
//   2. 온도 레지스터 할당: %r0, %r1, ... %r31 (최대 64개)
//   3. 레이블 생성 및 관리: label_loop_start, label_skip_filter 등
//   4. 물리 계획의 각 연산을 IR 명령어로 변환
// 구조:
//   - IRInstruction 구조체 (opcode + 연산 정보)
//   - IRBuilder 구조체 (명령어 배열 + 레지스터/레이블 할당)
//   - IR 생성 함수 (ir_emit_*)
//   - 물리 계획 변환 (ir_build_from_physical)
// ============================================================================

module ir_builder {
    // === 21개 IR Opcodes ===
    // 정수 연산
    const IR_LOAD_INT:  i32 = 1;    // %dst = immediate_int_value
    const IR_LOAD_STR:  i32 = 2;    // %dst = "string_value"
    const IR_LOAD_COL:  i32 = 3;    // %dst = current_row[col_idx]
    const IR_STORE_COL: i32 = 4;    // current_row[col_idx] = %src

    // 산술 연산
    const IR_ADD:       i32 = 5;    // %dst = %src1 + %src2
    const IR_SUB:       i32 = 6;    // %dst = %src1 - %src2
    const IR_MUL:       i32 = 7;    // %dst = %src1 * %src2
    const IR_DIV:       i32 = 8;    // %dst = %src1 / %src2

    // 비교 및 분기
    const IR_CMP:       i32 = 9;    // flags = cmp(%src1, %src2)
    const IR_JMP:       i32 = 10;   // goto label_id
    const IR_JZ:        i32 = 11;   // if zero goto label_id
    const IR_JNZ:       i32 = 12;   // if not zero goto label_id

    // 함수 호출
    const IR_CALL:      i32 = 13;   // %dst = call func_name(args)
    const IR_RET:       i32 = 14;   // return %src

    // 레이블 및 이동
    const IR_LABEL:     i32 = 15;   // label: (no operation)
    const IR_MOV:       i32 = 16;   // %dst = %src

    // 스택 연산
    const IR_PUSH:      i32 = 17;   // push %src
    const IR_POP:       i32 = 18;   // pop %dst

    // NOP
    const IR_NOP:       i32 = 19;   // no operation

    // 테이블 스캔
    const IR_NEXT_ROW:  i32 = 20;   // 다음 행으로 이동 (table_idx)

    // 집계
    const IR_AGGREGATE: i32 = 21;   // aggregate(agg_type, dst_reg, src_reg)

    // === 에러 코드 ===
    const IR_OK:             i32 = 0;
    const IR_ERR_FULL:       i32 = 100;  // 명령어 배열 가득 참
    const IR_ERR_INVALID_OP: i32 = 101;  // 유효하지 않은 opcode
    const IR_ERR_NO_REG:     i32 = 102;  // 온도 레지스터 부족

    // === 제한값 ===
    const MAX_IR_OPS:    i32 = 256;
    const MAX_TEMP_REGS: i32 = 64;
    const MAX_LABELS:    i32 = 128;

    // === 데이터 구조체 ===

    // 단일 IR 명령어
    struct IRInstruction {
        opcode:    i32;       // IR_LOAD_INT, IR_ADD 등
        dst_reg:   i32;       // 목적 레지스터 (%r0, %r1, ... as 0, 1, ...)
        src1_reg:  i32;       // 첫 번째 원본 레지스터
        src2_reg:  i32;       // 두 번째 원본 레지스터
        imm_int:   i64;       // 즉시값 (정수)
        imm_str:   string;    // 즉시값 (문자열)
        label_id:  i32;       // 레이블 ID (분기 시)
        func_name: string;    // 함수명 (CALL 시)

   675→        ib.instructions[ib.instr_count] = instr;
   676→        ib.instr_count = ib.instr_count + 1;
   677→        return IR_OK;
   678→    }
